阅读程序，写出输出结果：
#include <stdio.h>
int main(void)
{
    FILE *fp;
    char s[10];
    fp=fopen("text.dat","w");
    fputs("welcome",fp);
    fclose(fp);
    fp=fopen("text.dat","a+");
    fprintf(fp,"%d",55);
    rewind(fp);
    fscanf(fp,"%s",s);
    puts(s);
    fclose(fp);
    return 0;
}

阅读程序，写出输出结果：
#include <stdio.h>
int main(void)
{
    FILE *fp;
    int i;
    char a[4]={'a','b','c','d'}, b;
    fp=fopen("text.dat","wb");
    for(i=0;i<4;i++)
        fwrite(&a[i],sizeof(char),1,fp);
    fclose(fp);
    fp=fopen("text.dat","rb");
    fseek(fp,-3L*sizeof(char),SEEK_END);
    fread(&b,sizeof(char),1,fp);
    fclose(fp);
    printf("%c\n",b);
    return 0;
}

edge.stem:
阅读程序，写出输出结果（假设 text.dat 之前不存在或内容任意）：
#include <stdio.h>
int main(void)
{
    FILE *fp;
    int i, m, n;
    fp=fopen("text.dat","w+");
    for(i=1;i<5;i++)
    {
        fprintf(fp,"%d",i);
        if(i%3==0)
            fprintf(fp," ");
    }
    rewind(fp);
    fscanf(fp,"%d%d",&m,&n);
    printf("%d,%d\n",m,n);
    fclose(fp);
    return 0;
}
